-- Section 15 A10: private assignment decisions and durable execution ledger.
-- Deliberately does not alter marketplace source_service constraints.
CREATE TABLE IF NOT EXISTS fleet_partner_private_assignments(
 id text PRIMARY KEY,organization_id text NOT NULL REFERENCES fleet_partner_organizations(id) ON DELETE RESTRICT,branch_id text NOT NULL REFERENCES fleet_partner_branches(id) ON DELETE RESTRICT,
 work_origin text NOT NULL CHECK(work_origin IN('PRIVATE_ORDER','PRIVATE_SHIPMENT','ROUTE_STOP')),private_order_id text REFERENCES fleet_partner_private_orders(id) ON DELETE RESTRICT,shipment_id text REFERENCES fleet_partner_shipments(id) ON DELETE RESTRICT,route_stop_id text,
 provider_membership_id text NOT NULL,provider_id text NOT NULL,vehicle_or_truck_reference text NOT NULL DEFAULT '',execution_service text NOT NULL CHECK(execution_service IN('DISPATCH','TAXI','HAULING')),
 status text NOT NULL DEFAULT 'PENDING_PROVIDER_RESPONSE' CHECK(status IN('CREATED','PENDING_PROVIDER_RESPONSE','ACCEPTED','READY_FOR_EXECUTION','IN_PROGRESS','COMPLETED','DECLINED','EXPIRED','CANCELLED','REASSIGNMENT_REQUIRED')),
 response_deadline timestamptz NOT NULL,accepted_at timestamptz,declined_at timestamptz,expired_at timestamptz,cancelled_at timestamptz,decline_reason text NOT NULL DEFAULT '',decline_note text NOT NULL DEFAULT '',replacement_assignment_id text,
 version bigint NOT NULL DEFAULT 1,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK((work_origin='PRIVATE_ORDER' AND private_order_id IS NOT NULL)OR(work_origin='PRIVATE_SHIPMENT' AND shipment_id IS NOT NULL)OR(work_origin='ROUTE_STOP' AND route_stop_id IS NOT NULL)),UNIQUE(organization_id,id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fleet_private_assignment_active_work ON fleet_partner_private_assignments(organization_id,work_origin,COALESCE(private_order_id,''),COALESCE(shipment_id,''),COALESCE(route_stop_id,'')) WHERE status IN('CREATED','PENDING_PROVIDER_RESPONSE','ACCEPTED','READY_FOR_EXECUTION','IN_PROGRESS');
CREATE INDEX IF NOT EXISTS idx_fleet_private_assignment_expiry ON fleet_partner_private_assignments(response_deadline) WHERE status='PENDING_PROVIDER_RESPONSE';
CREATE TABLE IF NOT EXISTS fleet_partner_private_assignment_decisions(id text PRIMARY KEY,organization_id text NOT NULL,assignment_id text NOT NULL REFERENCES fleet_partner_private_assignments(id) ON DELETE RESTRICT,provider_id text NOT NULL,decision text NOT NULL CHECK(decision IN('ACCEPT','DECLINE')),reason_code text NOT NULL DEFAULT '',safe_note text NOT NULL DEFAULT '',safety_protected boolean NOT NULL DEFAULT false,idempotency_key text NOT NULL,request_fingerprint text NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),UNIQUE(assignment_id));
CREATE TRIGGER trg_fleet_private_assignment_decisions_append_only BEFORE UPDATE OR DELETE ON fleet_partner_private_assignment_decisions FOR EACH ROW EXECUTE FUNCTION fleet_partner_forbid_mutation();
CREATE TABLE IF NOT EXISTS fleet_partner_private_assignment_history(id text PRIMARY KEY,organization_id text NOT NULL,assignment_id text NOT NULL REFERENCES fleet_partner_private_assignments(id) ON DELETE RESTRICT,previous_status text NOT NULL,new_status text NOT NULL,reason_code text NOT NULL DEFAULT '',actor_type text NOT NULL,actor_reference text NOT NULL,correlation_id text NOT NULL DEFAULT '',occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER trg_fleet_private_assignment_history_append_only BEFORE UPDATE OR DELETE ON fleet_partner_private_assignment_history FOR EACH ROW EXECUTE FUNCTION fleet_partner_forbid_mutation();
CREATE TABLE IF NOT EXISTS fleet_partner_private_execution_operations(
 id text PRIMARY KEY,organization_id text NOT NULL,settlement_organization_id text NOT NULL,executing_provider_id text NOT NULL,organization_membership_id text NOT NULL,private_order_id text NOT NULL,shipment_id text NOT NULL,assignment_id text NOT NULL REFERENCES fleet_partner_private_assignments(id) ON DELETE RESTRICT,contract_reference text NOT NULL DEFAULT '',quotation_reference text NOT NULL DEFAULT '',execution_service text NOT NULL CHECK(execution_service IN('DISPATCH','TAXI','HAULING')),
 status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','SUBMITTING','OUTCOME_UNKNOWN','CONFIRMED','FAILED','CANCELLATION_PENDING','CANCELLED','RECONCILIATION_REQUIRED')),idempotency_key text NOT NULL,request_fingerprint text NOT NULL,canonical_request_reference text NOT NULL DEFAULT '',canonical_trip_reference text NOT NULL DEFAULT '',source_version bigint NOT NULL DEFAULT 0,attempts integer NOT NULL DEFAULT 0,last_error_code text NOT NULL DEFAULT '',next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_owner text,lease_expires_at timestamptz,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,idempotency_key),UNIQUE(assignment_id)
);
CREATE INDEX IF NOT EXISTS idx_fleet_private_execution_claim ON fleet_partner_private_execution_operations(next_attempt_at) WHERE status IN('PENDING','OUTCOME_UNKNOWN','CANCELLATION_PENDING','RECONCILIATION_REQUIRED');
CREATE TABLE IF NOT EXISTS fleet_partner_private_execution_attempts(id text PRIMARY KEY,organization_id text NOT NULL,operation_id text NOT NULL REFERENCES fleet_partner_private_execution_operations(id) ON DELETE RESTRICT,attempt integer NOT NULL,outcome text NOT NULL,safe_error_code text NOT NULL DEFAULT '',occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER trg_fleet_private_execution_attempts_append_only BEFORE UPDATE OR DELETE ON fleet_partner_private_execution_attempts FOR EACH ROW EXECUTE FUNCTION fleet_partner_forbid_mutation();
INSERT INTO fleet_partner_permissions(code,category,description,is_active)VALUES('private_assignments.read','private_assignments','Read private assignments',true),('private_assignments.manage','private_assignments','Create, cancel and reassign private assignments',true),('private_assignments.respond','private_assignments','Respond to selected private assignments',true),('private_execution.read','private_execution','Read private execution operations',true),('private_execution.manage','private_execution','Manage private execution operations',true)ON CONFLICT(code)DO UPDATE SET category=EXCLUDED.category,description=EXCLUDED.description,is_active=true;
INSERT INTO fleet_partner_role_permissions(role_id,permission_code)SELECT 'rol_system_owner',code FROM fleet_partner_permissions WHERE code LIKE 'private_%' ON CONFLICT DO NOTHING;INSERT INTO fleet_partner_role_permissions(role_id,permission_code)SELECT 'rol_system_operations',code FROM fleet_partner_permissions WHERE code IN('private_assignments.read','private_assignments.manage','private_execution.read','private_execution.manage')ON CONFLICT DO NOTHING;
